module lfsr8(input clk, input rst_n, input en, output reg [7:0] q);
  always @(posedge clk) begin
    if (!rst_n) q <= 8'h01;
    else if (en) q <= {q[6:0], q[7]^q[5]^q[4]^q[3]};
  end
endmodule

module lfsr8(input clk, input rst_n, input en, output [7:0] q);
  reg [7:0] r;
  assign q = r;
  wire fb = r[7]^r[5]^r[4]^r[3];
  always @(posedge clk)
    if (!rst_n) r <= 8'h01;
    else if (en) begin r[7:1] <= r[6:0]; r[0] <= fb; end
endmodule
